mapper.select:
select nm.*,nr.*,ai.user_name as dname from new_medical_examination_records nm left join new_reg nr on nm.reg_id=nr.id
LEFT JOIN `yh_user_make_card` AS c ON nr.`user_code` = c.`User_Code`
LEFT JOIN yh_user_admin_info AS ai ON c.doctor = ai.id




   and  nr.name LIKE CONCAT('%', #{name}, '%')


    and  nr.work_unit =#{workUnit}


    and  nm.stage =#{stage}


    and  nm.reg_id =#{regId}



    and  nm.marriage =#{marriage}


    and  nm.occupation =#{occupation}



    and  nm.gender =#{gender}


    and  DATE_FORMAT(nm.v16, '%Y') =#{v16}



    and  nm.v18 =#{v18}


LIMIT #{begin}, #{limit};

select count(*) from new_medical_examination_records nm left join new_reg nr on nm.reg_id=nr.id
LEFT JOIN `yh_user_make_card` AS c ON nr.`user_code` = c.`User_Code`
LEFT JOIN yh_user_admin_info AS ai ON c.doctor = ai.id


    and  nr.name LIKE CONCAT('%', #{name}, '%')


    and  nr.work_unit =#{workUnit}


    and  nm.stage =#{stage}


    and  nm.reg_id =#{regId}



    and  nm.marriage =#{marriage}


    and  nm.occupation =#{occupation}



